@font-face{font-family:'Noto Sans Bengali';font-style:normal;font-weight:400;src:url('file://<?= e(public_path('fonts/NotoSansBengali-Regular.ttf')) ?>') format('truetype')}@font-face{font-family:'Noto Sans Bengali';font-style:normal;font-weight:700;src:url('file://<?= e(public_path('fonts/NotoSansBengali-Bold.ttf')) ?>') format('truetype')}@page{margin:26px 30px}body{font-family:'Noto Sans Bengali','DejaVu Sans',sans-serif;color:#18212f;font-size:10px;line-height:1.48}h1,h2,h3,p{margin:0}.hero{background:#111827;color:#fff;padding:20px 22px;border-radius:8px}.eyebrow{color:#93c5fd;text-transform:uppercase;letter-spacing:1.2px;font-size:8px;font-weight:bold}.hero h1{font-size:22px;margin:7px 0 5px;font-weight:bold}.hero p{color:#d1d5db}.meta{margin-top:8px;color:#cbd5e1;font-size:9px}.section{margin-top:19px}.section h2{border-left:4px solid #2563eb;padding-left:8px;font-size:14px;color:#111827;margin-bottom:8px}.summary{width:100%;border-collapse:separate;border-spacing:8px 0;margin-left:-8px}.summary td{width:33%;background:#eff6ff;border:1px solid #bfdbfe;padding:10px;border-radius:5px;vertical-align:top}.label{color:#475569;font-size:8px;text-transform:uppercase;font-weight:bold}.value{color:#0f172a;font-size:16px;font-weight:bold;margin-top:3px}table.costs{width:100%;border-collapse:collapse}.costs th{background:#e8eef9;color:#25344f;padding:7px 8px;text-align:left;font-weight:bold}.costs td{border-bottom:1px solid #e5e7eb;padding:7px 8px}.right{text-align:right!important}.offer{border:1px solid #cbd5e1;border-radius:7px;margin:0 0 11px;padding:11px 12px;page-break-inside:avoid}.provider{color:#2563eb;font-size:8px;font-weight:bold;text-transform:uppercase;letter-spacing:.6px}.offer h3{font-size:11px;margin:3px 0 5px;color:#0f172a}.source{color:#475569;margin-bottom:8px}.recommendation{background:#ecfdf5;border-left:3px solid #10b981;padding:8px 9px;color:#064e3b}.link{color:#1d4ed8;font-size:8px;overflow-wrap:break-word;margin-top:7px}.empty{background:#fffbeb;border:1px solid #fde68a;padding:12px;color:#78350f;border-radius:6px}.foot{margin-top:18px;color:#64748b;font-size:8px;border-top:1px solid #e2e8f0;padding-top:8px}
</style></head><body>
<div class="hero"><div class="eyebrow">Personalized savings planner</div><h1>Savings Offers &amp; Shopping Advice</h1><p>A personal report based on your spending patterns and live offer searches.</p><div class="meta">Period: <?= e($from->format('d M Y')) ?> – <?= e($to->format('d M Y')) ?> &nbsp;|&nbsp; Location: <?= e($location) ?> &nbsp;|&nbsp; All amounts: ৳ (Taka)</div></div>
<div class="section"><table class="summary"><tr><td><div class="label">Total spending</div><div class="value">৳<?= e(number_format($total,0)) ?></div></td><td><div class="label">Expense categories</div><div class="value"><?= e(count($spending)) ?></div></td><td><div class="label">Average period</div><div class="value"><?= e($months) ?> month<?= $months === 1 ? '' : 's' ?></div></td></tr></table></div>
<div class="section"><h2>Your spending priorities</h2><table class="costs"><tr><th>Category</th><th class="right">Period spending</th><th class="right">Monthly average</th></tr><?php foreach(array_slice($spending,0,8) as $row): ?><tr><td><?= e($row['category']) ?></td><td class="right">৳<?= e(number_format((float)$row['amount'],0)) ?></td><td class="right">৳<?= e(number_format((float)$row['amount']/max(1,$months),0)) ?></td></tr><?php endforeach; ?></table></div>
<div class="section"><h2>Offers and recommendations for you</h2><?php if($offers === []): ?><div class="empty"><strong>No live offers found</strong><br><?= e($searchStatus ?: 'Please try again later.') ?></div><?php else: ?><?php foreach($offers as $index => $offer): ?><div class="offer"><div class="provider">Offer <?= e($index+1) ?> · <?= e($offer['provider']) ?></div><h3><?= e($offer['focus']) ?></h3><p class="source"><?= e($offer['source']) ?></p><div class="recommendation"><strong>Recommendation</strong><br><?= e($offer['recommendation']) ?></div><div class="link">Source and terms: <?= e($offer['url']) ?></div></div><?php endforeach; ?><?php endif; ?></div>
<p class="foot">Important: Offer terms, availability, location, minimum order, and eligibility may change. Verify details at the source link before purchasing. Potential savings are shown only when the source clearly states a discount.</p>
</body></html>
